const ensure = (condition, message) => {
	if (!condition) {
		throw new Error(message);
	}
};
const rows = msg.payload;
const test = msg.test;
const expectedSize = test.batchCount === test.expectedBatches - 1 ? 3 : 5;

ensure(Array.isArray(rows), 'Split payload is not an array');
ensure(msg.parts && msg.parts.type === 'array', 'Split sequence metadata is missing');
ensure(msg.parts.index === test.batchCount, `Expected batch index ${test.batchCount}, got ${msg.parts.index}`);
ensure(rows.length === expectedSize, `Expected ${expectedSize} rows in batch ${test.batchCount}, got ${rows.length}`);
if (test.partsId === null) {
	test.partsId = msg.parts.id;
}
ensure(msg.parts.id === test.partsId, 'Sequence ID changed between batches');
for (let index = 0; index < rows.length; index++) {
	const expectedId = test.batchCount * 5 + index + 1;
	ensure(rows[index].id === expectedId, `Expected row ${expectedId}, got ${rows[index].id}`);
}
if (test.batchCount === test.expectedBatches - 1) {
	ensure(msg.complete === true, 'Final batch is not marked complete');
	ensure(msg.parts.count === test.expectedBatches, `Expected ${test.expectedBatches} batches, got ${msg.parts.count}`);
} else {
	ensure(msg.complete !== true, `Batch ${test.batchCount} was marked complete too early`);
	ensure(msg.parts.count === undefined, `Batch ${test.batchCount} exposed a premature count`);
}
msg.query = 'UPDATE node_red_postgresql_test SET processed = TRUE WHERE id = ANY($1::integer[])';
msg.params = [rows.map((row) => row.id)];
test.batchCount++;
return msg;

const expectedUpdated = msg.params[0].length;
if (msg.pgsql.command !== 'UPDATE' || msg.pgsql.rowCount !== expectedUpdated) {
	throw new Error(`Expected UPDATE of ${expectedUpdated} rows, got ${msg.pgsql.command} ${msg.pgsql.rowCount}`);
}
msg.test.updatedRows += msg.pgsql.rowCount;
if (msg.complete) {
	delete msg.query;
	delete msg.params;
	return [msg, null];
}
msg.test.tickCount++;
return [null, { tick: true }];

const result = msg.payload[0];
const test = msg.test;
if (test.batchCount !== test.expectedBatches || test.tickCount !== test.expectedBatches - 1 || test.updatedRows !== test.expectedRows) {
	throw new Error(`Processed ${test.batchCount} batches, ${test.tickCount} ticks, and ${test.updatedRows} rows`);
}
if (!result || result.total !== test.expectedRows || result.processed !== test.expectedRows || result.value_sum !== 2760) {
	throw new Error(`Unexpected aggregate result: ${JSON.stringify(result)}`);
}
return msg;

